mapper.select:
SELECT c.id, c.user_id, c.company_code, c.name, c.logo, c.industry, c.create_time, COUNT(e.id) AS total_count, COUNT(CASE WHEN e.type = '八股文' THEN 1 END) AS bagu_count, COUNT(CASE WHEN e.type = '算法题' THEN 1 END) AS algo_count, COUNT(CASE WHEN e.status = '已掌握' THEN 1 END) AS mastered_count FROM tb_company c LEFT JOIN tb_entry e ON c.id = e.company_id AND e.user_id = c.user_id WHERE c.user_id = #{userId}
AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR c.industry LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY c.id, c.user_id, c.company_code, c.name, c.logo, c.industry, c.create_time ORDER BY c.id ASC
